export type AgnesState = {
	hp: number;
	handcardCount: number;
};

export function isEntryTarget(agnes: AgnesState, target: AgnesState): boolean {
	return target.hp > agnes.hp || target.handcardCount > agnes.handcardCount;
}

export function getEntryTargetAiScore(research: number, hpAdvantage: number, handAdvantage: number, attitude: number): number {
	const normalizedResearch = Math.max(0, Math.trunc(research));
	const researchValue = normalizedResearch === 1 ? 30 : normalizedResearch >= 2 ? 20 : 0;
	const differenceValue = (Math.max(0, hpAdvantage) + Math.max(0, handAdvantage)) * 1.5;
	const allyPreference = Math.max(-5, Math.min(5, attitude)) * 0.35;
	return researchValue + differenceValue + allyPreference;
}

export function shouldChooseEntryCard(attitudeToAgnes: number, agnesHasHandcard: boolean): boolean {
	return agnesHasHandcard && attitudeToAgnes > 0;
}

export function shouldUseKuAsShanAi(ku: number, ordinaryShanCount: number): boolean {
	return canUseKuAsShan(ku) && ordinaryShanCount <= 0;
}

export function getEntryControls(agnesHandcardCount: number): string[] {
	return agnesHandcardCount > 0 ? ["获得一张手牌", "摸一张牌"] : ["摸一张牌"];
}

export function grantsRepeatedResearchDraw(previousResearch: number): boolean {
	return previousResearch > 0;
}

export function canUseKuAsShan(ku: number): boolean {
	return ku > 0;
}

export function canUseLimitedRecovery(ku: number, hp: number, maxHp: number, hasUsed = false): boolean {
	return !hasUsed && ku >= 2 && hp < maxHp;
}

export function getRecoveryControls(ku: number): string[] {
	return Array.from({ length: Math.max(0, ku) }, (_, index) => `${index + 1}枚`);
}

export function getActualRemovedKu(chosen: number, currentKu: number): number {
	return Math.max(0, Math.min(Math.trunc(chosen), Math.trunc(currentKu)));
}

export function shouldTriggerKeshu(isOtherPlayer: boolean, cardType: string, research: number): boolean {
	return isOtherPlayer && (cardType === "trick" || cardType === "delay") && research >= 2;
}

export function getKeshuDrawCount(hasUsedLimitedRecovery: boolean): number {
	return hasUsedLimitedRecovery ? 2 : 1;
}
